import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"VM is an Operation, Not a Subsystem","description":"","frontmatter":{"title":"VM is an Operation, Not a Subsystem","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"accepted","supersedes":["ADR-0027"],"status_note":"Accepted — the VM is an operation; the VM/runtime crate families dissolve."},"headers":[],"relativePath":"handl/project/adrs/0040-vm-is-an-operation-not-a-subsystem.md","filePath":"vendored/handl/project/adrs/0040-vm-is-an-operation-not-a-subsystem.md"}`),a={name:`handl/project/adrs/0040-vm-is-an-operation-not-a-subsystem.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0040-vm-is-an-operation-not-a-subsystem" tabindex="-1">ADR-0040: VM is an Operation, Not a Subsystem <a class="header-anchor" href="#adr-0040-vm-is-an-operation-not-a-subsystem" aria-label="Permalink to “ADR-0040: VM is an Operation, Not a Subsystem”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Dissolve <code>plugin-vm-*</code> and <code>plugin-runtime-*</code>.</strong> Evaluation uses the platform&#39;s <code>Eval</code> operation, <code>Behavior&lt;Eval&gt;</code> and <code>BasicEvaluator</code> — the same pattern as every other operation.</li><li><strong>No <code>VirtualMachine</code> trait, no <code>Value</code> trait, no <code>Runtime</code> operation, no <code>V</code> genericity</strong>, and no <code>Expr</code>/<code>Pattern</code>/<code>HandlerClause</code> intermediate representation.</li><li><strong>Eval handlers are granular <code>Behavior&lt;Eval&gt;</code> plugins</strong>, one per AST kind, each decoding <code>AstNode.payload</code> to <code>serde_json::Value</code>.</li><li><strong><code>EvalRequest</code> carries <code>EvalContext</code></strong> (scopes, evaluator handle, modules, limits, call count); recursion is <code>ctx.eval(&amp;child)</code> back through the evaluator.</li><li><strong><code>EvalContext</code> lives in <code>plugin-ext-eval</code></strong>, <code>EvalRequest</code> in <code>platform</code>; eval is special at the request level, never at the trait level.</li><li><strong>Function registration collapses to <code>Module</code>/<code>ModuleRuntime</code></strong> with a non-generic <code>Function</code> trait over <code>serde_json::Value</code>.</li><li><strong>There is no bundled interpreter target</strong>: the 11 <code>plugin-eval-*</code> plugins are the tree-walk target; a compiler target is a set of <code>Compile</code> rules instead.</li><li><strong>One cutover.</strong> The old VM/runtime crates and <code>lego.rs</code> (<code>ExprHandler</code>/<code>LegoVm</code>) are deleted; no dual path.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The VM was a privileged subsystem with its own traits, genericity and IR, so it re-implemented what <code>Behavior</code> already provides and blocked the JSON-boundary model. Moving eval onto the operation pattern makes one dispatch path for every stage and deletes a crate family.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep <code>VirtualMachine</code>/<code>Value</code> traits</strong> — they existed only for the subsystem.</li><li><strong>Keep <code>plugin-runtime-*</code></strong> — six crates duplicating <code>plugin-lib-*</code>.</li><li><strong>Ship a bundled interpreter target</strong> — the target is the set of eval plugins the kit loads.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Every operation uses one behavior trait; eval is not special.</li><li>Values are <code>serde_json::Value</code>; child nodes cross the JSON boundary.</li><li>Targets are plugin sets: interpreter = <code>Eval</code> rules, compiler = <code>Compile</code> rules.</li><li>The crate list shrinks; function registration has one mechanism.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>platform</code> — <code>EvalRequest</code>.</li><li><code>plugin-ext-eval</code> — <code>EvalContext</code>, the contract.</li><li><code>plugin-eval-*</code> — the 11 tree-walk rules; <code>plugin-module</code> — registration.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>Handler mapping, crate taxonomy, context and the explicit not-kept list: <a href="./../design/0040-vm-is-an-operation-not-a-subsystem.html"><code>design/0040-vm-is-an-operation-not-a-subsystem.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};